package com.medtrack.supplier.entity;
import com.medtrack.shared.model.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="suppliers") public class Supplier extends BaseEntity { @Column(nullable=false) private String name; @Column(nullable=false,unique=true) private String code; @Column(name="contact_email") private String contactEmail; @Column(name="contact_phone") private String contactPhone; private String address; protected Supplier(){} public Supplier(String name,String code,String email,String phone,String address){this.name=name;this.code=code;this.contactEmail=email;this.contactPhone=phone;this.address=address;} public void update(String name,String email,String phone,String address){this.name=name;this.contactEmail=email;this.contactPhone=phone;this.address=address;} public String getName(){return name;} public String getCode(){return code;} public String getContactEmail(){return contactEmail;} public String getContactPhone(){return contactPhone;} public String getAddress(){return address;} }
